contract InvMutTest {
    C c;
    address lastFrom;
    address lastTo;
    uint lastV;
    bool calledBack;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public payable {
        require(to == address(this));
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok;
        ok = c.transfer(from, address(this), tos, v);
        assert(ok && calledBack && lastFrom == from && lastTo == to && lastV == v);
    }
    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (msg.sender == address(c) && data.length == 100) {
            bytes4 sel; address f; address t; uint val;
            (sel, f, t, val) = abi.decode(data, (bytes4, address, address, uint256));
            if (sel == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
                calledBack = true;
                lastFrom = f;
                lastTo = t;
                lastV = val;
            }
        }
        return abi.encode(true);
    }
    receive() external payable {}
}

