contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory tos, uint v) public payable {
        require(true);
        // address(this) has no transferFrom, so every low-level call returns success=false
        bool reverted;
        bool ok = true;
        if (tos.length > 0) {
            // call with a nonempty list: the loop's require(_s) must fail
            bool r;
            try c.transfer(address(this), address(this), tos, v) { r = false; } catch { r = true; }
            ok = r;
        }
        // call with empty list: require(_tos.length > 0) must fail
        address[] memory empty = new address[](0);
        bool r2;
        try c.transfer(address(this), address(this), empty, v) { r2 = false; } catch { r2 = true; }
        reverted = ok && r2;
        assert(reverted);
    }
    receive() external payable {}
}

