contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0);
        uint balBefore = address(c).balance;
        bool reverted;
        bool ret = false;
        // caddress is the zero address: the low-level transferFrom call to it succeeds
        try c.transfer(from, address(0), tos, v) returns (bool r) { reverted = false; ret = r; }
        catch { reverted = true; }
        assert(reverted || (ret && address(c).balance == balBefore));
    }
